// Transport for the opaque encrypted database. Talks to the Phase 5 blob
// endpoints; no cryptography happens here (the bytes are already encrypted).

import axios from '@nextcloud/axios';
import { generateUrl } from '@nextcloud/router';

const DB_URL = '/apps/upm/db';

/**
 * Download the encrypted database, or `null` when the server has none yet
 * (HTTP 404).
 */
export async function getDb(): Promise<Uint8Array | null> {
  const response = await axios.get(generateUrl(DB_URL), {
    responseType: 'arraybuffer',
    validateStatus: (status) => status === 200 || status === 404,
  });
  if (response.status === 404) {
    return null;
  }
  return new Uint8Array(response.data as ArrayBuffer);
}

/** Upload the encrypted database as raw bytes. */
export async function putDb(bytes: Uint8Array): Promise<void> {
  await axios.put(generateUrl(DB_URL), bytes, {
    headers: { 'Content-Type': 'application/octet-stream' },
  });
}

/** Delete the stored database (a missing file counts as success). */
export async function deleteDb(): Promise<void> {
  await axios.delete(generateUrl(DB_URL));
}
